#[test]
fn test_names_are_interned_and_well_known_ids_resolve() {
    let ar: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let d: i32 = pt_parse_text(&crate::testport::text_blob("<</Type /Page /Kids [1 0 R] /Type#20X /Type /Media#42ox [0 0 612.5 792]>>")[..], ar);
    let ty: i32 = pl_dict_get(ar, d, pn_type());
    let kids: i32 = pl_dict_get(ar, d, pn_kids());
    let mb: i32 = pl_dict_get(ar, d, pn_media_box());
    let kid0: i32 = pl_first(ar, kids);
    crate::testport::assert_that(d != 0, "parsed");
    crate::testport::assert_eq(pl_kind_of(ar, d), pl_k_dict(), "a dictionary");
    crate::testport::assert_eq(pl_kind_of(ar, ty), pl_k_name(), "/Type is a name");
    crate::testport::assert_that(pl_name_is(ar, ty, pn_type()) == 0, "/Page is not /Type");
    crate::testport::assert_eq(pl_dict_get(ar, d, pn_length()), 0, "an absent key answers 0");
    crate::testport::assert_eq(pl_kind_of(ar, kids), pl_k_array(), "/Kids is an array");
    crate::testport::assert_eq(pl_count(ar, kids), 1, "one kid");
    crate::testport::assert_eq(pl_kind_of(ar, kid0), pl_k_ref(), "a reference");
    crate::testport::assert_eq(pl_int_value(ar, kid0), 1, "to object 1");
    // `/Media#42ox` is `/MediaBox`: the escape is decoded BEFORE interning.
    crate::testport::assert_that(mb != 0, "/Media#42ox finds /MediaBox");
    crate::testport::assert_eq(pl_count(ar, mb), 4, "four numbers");
    // The first /Type is /Page, the key written twice is /Type#20X, and
    // the last /Type wins: its value is the LAST one.
    crate::testport::assert_eq(pl_kind_of(ar, ty), pl_k_name(), "last /Type");
}
