    crate::testport::assert_eq(pt_cp(&crate::testport::text_blob("-0.005")[..]), -1, "half rounds away from zero");
    crate::testport::assert_eq(pt_cp(&crate::testport::text_blob("12.5")[..]), 1250, "one decimal");
    crate::testport::assert_eq(pt_cp(&crate::testport::text_blob("0.1234567")[..]), 12, "many decimals");
    crate::testport::assert_eq(pt_cp(&crate::testport::text_blob("99999999999")[..]), 2147483647, "saturates");
