pub(crate) fn pt_sf(src: &[u8], which: i32) -> i32 {
    // One field of the stream parsed from src (an indirect object).
    let ar: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let z: i32 = pt_prep(ar, src);
    let s: i32 = pl_parse_indirect(src, ar, 0);
    let sd: i32 = pl_stream_dict(ar, s);
    let lh: i32 = pl_dict_get(ar, sd, pn_length());
    if z != 0 {
        return -1;
    }
    if which == 0 {
        return pl_objnum(ar);
    }
    if which == 1 {
        return pl_objgen(ar);
    }
    if which == 2 {
        return pl_kind_of(ar, s);
    }
    if which == 3 {
        return pl_stream_start(ar, s);
    }
    if which == 4 {
        return pl_stream_len(ar, s);
    }
    if which == 5 {
        return pl_stream_flags(ar, s);
    }
    return pl_int_value(ar, lh);
}
#[test]
fn test_stream_fields_of_an_indirect_object() {
    crate::testport::assert_eq(pt_sf(&crate::testport::text_blob("7 2 obj\n<</Length 5>>\nstream\nhello\nendstream\nendobj\n")[..], 0), 7, "object number");
    crate::testport::assert_eq(pt_sf(&crate::testport::text_blob("7 2 obj\n<</Length 5>>\nstream\nhello\nendstream\nendobj\n")[..], 1), 2, "generation");
    crate::testport::assert_eq(pt_sf(&crate::testport::text_blob("7 2 obj\n<</Length 5>>\nstream\nhello\nendstream\nendobj\n")[..], 2), pl_k_stream(), "a stream");
    crate::testport::assert_eq(pt_sf(&crate::testport::text_blob("7 2 obj\n<</Length 5>>\nstream\nhello\nendstream\nendobj\n")[..], 3), 29, "data starts after the end of line");
    crate::testport::assert_eq(pt_sf(&crate::testport::text_blob("7 2 obj\n<</Length 5>>\nstream\nhello\nendstream\nendobj\n")[..], 4), 5, "five bytes");
    crate::testport::assert_eq(pt_sf(&crate::testport::text_blob("7 2 obj\n<</Length 5>>\nstream\nhello\nendstream\nendobj\n")[..], 5), 0, "length trusted");
    crate::testport::assert_eq(pt_sf(&crate::testport::text_blob("7 2 obj\n<</Length 5>>\nstream\nhello\nendstream\nendobj\n")[..], 6), 5, "the dictionary");
    crate::testport::assert_eq(pt_sf(&crate::testport::text_blob("7 2 obj\n<</Length 3>>\nstream\nhello\nendstream\nendobj\n")[..], 5), 1, "a wrong length is scanned");
    crate::testport::assert_eq(pt_sf(&crate::testport::text_blob("7 2 obj\n<</Length 3>>\nstream\nhello\nendstream\nendobj\n")[..], 4), 5, "and the real length found");
}
