#[test]
fn test_every_truncation_of_a_fixture_parses_or_names_an_error() {
    let f: &[u8] = &crate::testport::test_file("pdf/minimal.pdf")[..];
    let n: i32 = crate::port::blob_len(f);
    let cut: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ar: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let mut cutn: i32 = 0;
    let mut i: i32 = 0;
    let mut guard: i32 = 0;
    let mut at: i32 = 0;
    let mut h: i32 = 0;
    let mut before: i32 = 0;
    while cutn < (n + 1) {
        crate::port::cells_drop(cut, 0);
        i = 0;
        while i < cutn {
            crate::port::cells_push(cut, crate::port::blob_u8(f, i));
            i += 1;
        }
        // As a token-level object stream from 0.
        pl_init(ar);
        pl_seek(ar, 0, cutn);
        guard = 0;
        h = 1;
        while (h != 0) && (guard < 2000) {
            before = pl_pos(ar);
            h = pl_parse(&crate::testport::cells_blob(cut)[..], ar);
            if (h != 0) && (pl_pos(ar) <= before) {
                h = 0;
            }
            guard += 1;
        }
        // And as an indirect object at the start of every line.
        at = 0;
        while at < cutn {
            pl_init(ar);
            pl_seek(ar, 0, cutn);
            pl_parse_indirect(&crate::testport::cells_blob(cut)[..], ar, at);
            // a stream's data ends inside the blob
            crate::testport::assert_that(pl_pos(ar) <= cutn, "the parse never ran past the end");
            at = pt_nl(f, at) + 1;
        }
        cutn += 1;
    }
}
